import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const world = $('#world');
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(76, innerWidth / innerHeight, 0.1, 260);
const renderer = new THREE.WebGLRenderer({ canvas: world, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

const MAPS = [
  { name: 'THE DUSTLINE', detail: 'Al Mazrah · 12:40 · Clear', ground: '#a18b68', sky: '#c4a878', fog: '#b5a17e', accent: '#c2a15f', kind: 'desert' },
  { name: 'NIGHT SHIFT', detail: 'Port Vela · 02:15 · Rain', ground: '#303b42', sky: '#1e2b37', fog: '#283744', accent: '#78a99e', kind: 'night' },
  { name: 'IRONWOOD', detail: 'Black Forest · 16:20 · Overcast', ground: '#52604a', sky: '#99a58f', fog: '#697565', accent: '#a8ad75', kind: 'forest' },
  { name: 'GRIDLOCK', detail: 'District 9 · 09:05 · Haze', ground: '#777a72', sky: '#a6a69a', fog: '#8f9289', accent: '#ba8158', kind: 'city' },
  { name: 'FROSTLINE', detail: 'Krasna Ridge · 11:30 · Snow', ground: '#aab4b7', sky: '#c8d4d7', fog: '#b6c3c6', accent: '#708d98', kind: 'snow' },
  { name: 'RED HARBOR', detail: 'Caldera Bay · 18:10 · Sunset', ground: '#76614c', sky: '#cf926c', fog: '#a87861', accent: '#c47c55', kind: 'harbor' },
];
let mapIndex = Math.floor(Math.random() * MAPS.length);
let activeMap = MAPS[mapIndex];
let mode = 'bots';
let playing = false, paused = false, gameOver = false;
let kills = 0, shots = 0, hits = 0, ammo = 30, health = 100;
let elapsed = 0, remaining = 480, lastTime = 0, lastShot = 0, reloading = false;
let yaw = 0, pitch = 0, velocityY = 0, recoil = 0, moving = false;
const keys = new Set();
const obstacles = [], bots = [], decor = [], tracers = [];
const raycaster = new THREE.Raycaster();
const moveVector = new THREE.Vector2();
const clock = new THREE.Clock();
const mat = (color, roughness = .86, metalness = .02) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {};
const gameCamera = new THREE.Group();
scene.add(gameCamera);
gameCamera.add(camera);

function clearWorld() {
  for (const object of [...decor, ...bots.map(b => b.group), ...tracers]) scene.remove(object);
  obstacles.length = 0; bots.length = 0; decor.length = 0; tracers.length = 0;
  for (const key of Object.keys(mats)) delete mats[key];
}
function addMesh(geo, material, parent, x, y, z, cast = true, receive = true) {
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z); mesh.castShadow = cast; mesh.receiveShadow = receive;
  parent.add(mesh); decor.push(mesh); return mesh;
}
function box(parent, x, y, z, w, h, d, material, obstacle = false) {
  const mesh = addMesh(new THREE.BoxGeometry(w, h, d), material, parent, x, y, z);
  if (obstacle) obstacles.push({ x, z, w, d, h, mesh });
  return mesh;
}
function cylinder(parent, x, y, z, r1, r2, h, material, segments = 10) {
  return addMesh(new THREE.CylinderGeometry(r1, r2, h, segments), material, parent, x, y, z);
}
function makeGroundTexture(kind) {
  const canvas = document.createElement('canvas'); canvas.width = canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const base = activeMap.ground; ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
  const seed = kind.length * 164 + mapIndex * 81; let n = seed;
  const rand = () => { n = (n * 1664525 + 1013904223) >>> 0; return n / 4294967296; };
  for (let i = 0; i < 2500; i++) {
    const shade = rand() > .5 ? 255 : 0; ctx.fillStyle = `rgba(${shade},${shade},${shade},${rand() * .075})`;
    ctx.fillRect(rand() * 256, rand() * 256, rand() * 4 + 1, rand() * 4 + 1);
  }
