function animate(now){
  requestAnimationFrame(animate);
  const dt=Math.min(.04,clock.getDelta());
  if(playing&&!paused){
    elapsed+=dt;remaining-=dt;if(remaining<=0){remaining=0;endGame(false);}else{$('#timer').textContent=formatTime(remaining);updatePlayer(dt);updateBots(dt,now/1000);if(fireHeld&&now-lastShot>135)shoot();if(Math.floor(elapsed*3)!==Math.floor((elapsed-dt)*3))updateMinimap();}
  }else if(!playing){
    gameCamera.position.set(Math.sin(now*.00012)*1.6,2.4+Math.sin(now*.0005)*.12,8+Math.cos(now*.00012)*1.3);
    gameCamera.rotation.set(-.08,Math.sin(now*.00012)*.15,0);
    const beacon=decor.find(o=>o.userData?.beacon);if(beacon)beacon.rotation.y+=dt*.4;
  }
  renderer.render(scene,camera);
}
function onResize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);}
window.addEventListener('resize',onResize);
window.addEventListener('blur',()=>{fireHeld=false;keys.clear();if(playing&&!paused&&!isMobile())pauseGame();});
world.addEventListener('contextmenu',e=>e.preventDefault());
updateMapCard();buildMap();updateMinimap();requestAnimationFrame(animate);

