function isBlocked(x,z,r=.45){return obstacles.some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r);}
function getSpawn(){for(let i=0;i<80;i++){const x=(Math.random()-.5)*70,z=(Math.random()-.5)*70;if(Math.abs(x)<20&&Math.abs(z)<20)continue;if(!isBlocked(x,z,.8))return{x,z};}return{x:30,z:30};}
function makeWeapon(){const gun=new THREE.Group();gun.position.set(.32,-.28,-.48);camera.add(gun);const black=new THREE.MeshStandardMaterial({color:'#202827',metalness:.78,roughness:.27}),polymer=new THREE.MeshStandardMaterial({color:'#39423c',metalness:.25,roughness:.55}),olive=new THREE.MeshStandardMaterial({color:'#69735d',metalness:.16,roughness:.52});const part=(geo,m,x,y,z)=>{const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;gun.add(o);return o;};part(new THREE.BoxGeometry(.13,.14,.56),polymer,0,0,0);part(new THREE.BoxGeometry(.105,.09,.38),black,0,.065,-.34);part(new THREE.CylinderGeometry(.027,.032,.42,12),black,0,.08,-.66).rotation.x=Math.PI/2;part(new THREE.BoxGeometry(.12,.22,.15),olive,0,-.17,.03).rotation.x=-.2;part(new THREE.BoxGeometry(.09,.17,.1),polymer,0,-.13,-.24);part(new THREE.BoxGeometry(.09,.06,.17),black,0,.15,-.26);part(new THREE.BoxGeometry(.17,.055,.12),black,0,.16,-.33);part(new THREE.BoxGeometry(.055,.1,.1),olive,.09,-.08,-.18);const sight=part(new THREE.BoxGeometry(.045,.065,.09),black,0,.16,-.59);const lens=new THREE.Mesh(new THREE.BoxGeometry(.022,.035,.01),new THREE.MeshBasicMaterial({color:'#a9e7c7'}));lens.position.set(0,.01,-.05);sight.add(lens);return gun;}
const weapon=makeWeapon();
function makeBot(id){const group=new THREE.Group(),colors=['#b17f57','#64775f','#7d7770','#667b88','#928064','#566d68'];const cloth=mat(colors[id%colors.length]),dark=mat('#26302d'),armor=mat(id%2?'#4b5650':'#666852'),skin=mat('#b48e70'),visor=new THREE.MeshStandardMaterial({color:'#202d2b',metalness:.55,roughness:.25,emissive:'#284c46',emissiveIntensity:.3});const add=(geo,m,x,y,z)=>{const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;group.add(o);return o;};add(new THREE.CapsuleGeometry(.34,.55,4,8),cloth,0,.97,0);add(new THREE.BoxGeometry(.57,.38,.27),armor,0,1.15,-.12);add(new THREE.SphereGeometry(.22,12,10),skin,0,1.78,-.01);add(new THREE.SphereGeometry(.24,12,8),dark,0,1.9,.015);add(new THREE.BoxGeometry(.35,.07,.07),visor,0,1.82,-.215);const legs=[];for(const x of [-.16,.16]){const leg=add(new THREE.CapsuleGeometry(.13,.43,3,6),dark,x,.38,0);legs.push(leg);add(new THREE.BoxGeometry(.24,.13,.4),dark,x,.11,-.06);}add(new THREE.BoxGeometry(.35,.46,.2),dark,0,1.13,.19);const rifle=add(new THREE.BoxGeometry(.07,.08,.56),dark,.47,.86,-.24);rifle.rotation.x=-.12;add(new THREE.BoxGeometry(.055,.16,.08),armor,.46,.73,-.17).rotation.x=-.2;const hpBg=new THREE.Sprite(new THREE.SpriteMaterial({color:0x101410,transparent:true,opacity:.8}));hpBg.position.set(0,2.4,0);hpBg.scale.set(.9,.1,1);group.add(hpBg);const hp=new THREE.Sprite(new THREE.SpriteMaterial({color:0xc8f169}));hp.position.set(0,2.4,-.01);hp.scale.set(.84,.055,1);group.add(hp);hpBg.userData.bar=hp;const s=getSpawn();group.position.set(s.x,0,s.z);scene.add(group);return{id,group,hp,hpBg,health:100,alive:true,x:s.x,z:s.z,targetX:s.x,targetZ:s.z,speed:1.45+Math.random()*.55,shootDelay:1+Math.random()*1.8,respawn:0,legs,phase:Math.random()*5,color:colors[id%colors.length]};}
function updateMapCard(){activeMap=MAPS[mapIndex];$('#map-name').textContent=activeMap.name;$('#map-detail').textContent=activeMap.detail;}
$('#map-cycle').addEventListener('click',()=>{mapIndex=(mapIndex+1+Math.floor(Math.random()*(MAPS.length-1)))%MAPS.length;updateMapCard();buildMap();});
for(const button of document.querySelectorAll('.mode-card'))button.addEventListener('click',()=>{document.querySelectorAll('.mode-card').forEach(b=>b.classList.remove('selected'));button.classList.add('selected');mode=button.dataset.mode;$('#online-note').hidden=mode!=='online';});
function isMobile(){return matchMedia('(pointer: coarse)').matches||innerWidth<700;}
function formatTime(seconds){const n=Math.max(0,Math.floor(seconds));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function addMessage(title,sub=''){const el=$('#center-message');el.innerHTML=`<span>${sub}</span><strong>${title}</strong>`;el.classList.add('visible');}
function hideMessage(){$('#center-message').classList.remove('visible');}
function startGame(){$('#menu-screen').hidden=true;$('#pause-screen').hidden=true;$('#end-screen').hidden=true;$('#hud').hidden=false;buildMap();kills=shots=hits=0;ammo=30;health=100;elapsed=0;remaining=480;gameOver=false;paused=false;playing=true;reloading=false;yaw=Math.random()*Math.PI*2;pitch=0;velocityY=0;gameCamera.position.set(0,1.7,0);gameCamera.rotation.set(0,yaw,0);camera.rotation.set(0,0,0);$('#score').textContent='00';$('#ammo').textContent='30';$('#ammo-bar').style.width='100%';$('#health-value').textContent='100';$('#health-fill').style.width='100%';$('#timer').textContent='08:00';$('#hud-map').textContent=activeMap.name;$('#killfeed').replaceChildren();for(let i=0;i<5;i++)bots.push(makeBot(i));addMessage('GET READY','RANDOM INSERTION');setTimeout(()=>{if(playing&&!paused)hideMessage();},1700);if(!isMobile())world.requestPointerLock?.();$('#mobile-hint').style.display=isMobile()?'block':'none';}
function pauseGame(){if(!playing||gameOver)return;paused=true;$('#pause-screen').hidden=false;document.exitPointerLock?.();}
function resumeGame(){if(!playing||gameOver)return;paused=false;$('#pause-screen').hidden=true;if(!isMobile())world.requestPointerLock?.();}
function endGame(won=false){playing=false;gameOver=true;document.exitPointerLock?.();$('#hud').hidden=true;$('#end-screen').hidden=false;$('#end-title').textContent=won?'Dominant performance.':'Operation complete.';$('#end-subtitle').textContent=won?'You own this battlefield.':'Every deployment makes you sharper.';$('#end-kills').textContent=String(kills).padStart(2,'0');$('#end-accuracy').textContent=shots?`${Math.round(hits/shots*100)}%`:'0%';$('#end-time').textContent=formatTime(elapsed);}
$('#deploy-btn').addEventListener('click',startGame);$('#again-btn').addEventListener('click',startGame);$('#resume-btn').addEventListener('click',resumeGame);$('#leave-btn').addEventListener('click',()=>{playing=false;paused=false;$('#pause-screen').hidden=true;$('#hud').hidden=true;$('#menu-screen').hidden=false;buildMap();});$('#end-menu-btn').addEventListener('click',()=>{$('#end-screen').hidden=true;$('#menu-screen').hidden=false;buildMap();});$('.settings-btn').addEventListener('click',()=>{if(playing)pauseGame();else $('#online-note').hidden=!$('#online-note').hidden;});

