const minimap=$('#minimap'),mapCtx=minimap.getContext('2d');
let toastTimer=0,hitMarkerTimer=0,damageTimer=0,flashTimer=0,ammoReserve=180,jumpQueued=false;
function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),1250);}
function updateAmmo(){ $('#ammo').textContent=String(ammo).padStart(2,'0');$('#ammo-bar').style.width=`${ammo/30*100}%`; }
function reload(){if(!playing||paused||reloading||ammo===30||ammoReserve<=0)return;reloading=true;$('#reload-indicator').hidden=false;setTimeout(()=>{if(!playing)return;const amount=Math.min(30-ammo,ammoReserve);ammo+=amount;ammoReserve-=amount;reloading=false;$('#reload-indicator').hidden=true;updateAmmo();},1050);}
function damagePlayer(amount){if(!playing||paused)return;health=Math.max(0,health-amount);$('#health-value').textContent=String(health);$('#health-fill').style.width=`${health}%`;const v=$('#damage-vignette');v.style.opacity='.72';clearTimeout(damageTimer);damageTimer=setTimeout(()=>v.style.opacity='0',210);if(health<=0){health=100;$('#health-value').textContent='100';$('#health-fill').style.width='100%';const s=getSpawn();gameCamera.position.set(s.x,1.7,s.z);showToast('REDEPLOYED');}}
function showHit(){const el=$('#hit-marker');el.classList.add('active');clearTimeout(hitMarkerTimer);hitMarkerTimer=setTimeout(()=>el.classList.remove('active'),130);}
function addKillfeed(text){const feed=$('#killfeed'),entry=document.createElement('div');entry.className='kill-entry';entry.innerHTML=`<b>YOU</b><span>✕</span>${text}`;feed.prepend(entry);while(feed.children.length>4)feed.lastElementChild.remove();setTimeout(()=>entry.remove(),4300);}
function killBot(bot){bot.alive=false;bot.health=0;scene.remove(bot.group);bot.respawn=4+Math.random()*3;kills++;$('#score').textContent=String(kills).padStart(2,'0');addKillfeed(`OPERATOR ${String(bot.id+1).padStart(2,'0')}`);if(kills>=20)endGame(true);}
function fire(){if(!playing||paused||reloading||gameOver)return;if(ammo<=0){showToast('MAGAZINE EMPTY · R TO RELOAD');return;}const now=performance.now();if(now-lastShot<115)return;lastShot=now;ammo--;shots++;updateAmmo();recoil=Math.min(.14,recoil+.045);weapon.position.z=-.48+recoil;weapon.rotation.x=-recoil*.35;
  raycaster.setFromCamera(new THREE.Vector2(0,0),camera);raycaster.far=95;const targets=bots.filter(b=>b.alive).map(b=>b.group);const hit=raycaster.intersectObjects(targets,true)[0];if(hit){const bot=bots.find(b=>b.alive&&b.group===hit.object.parent);let target=bot;if(!target)target=bots.find(b=>b.alive&&b.group.children.some(c=>c===hit.object||c.children.includes(hit.object)));if(target){hits++;target.health-=aiming?52:34;target.hp.scale.x=.84*Math.max(0,target.health/100);showHit();if(target.health<=0)killBot(target);}}
  const flash=new THREE.PointLight(0xffc36a,3,3);flash.position.set(.32,-.22,-.92);weapon.add(flash);setTimeout(()=>weapon.remove(flash),45);
}
function movePlayer(dt){let forward=0,side=0;if(keys.has('KeyW')||keys.has('ArrowUp'))forward++;if(keys.has('KeyS')||keys.has('ArrowDown'))forward--;if(keys.has('KeyD')||keys.has('ArrowRight'))side++;if(keys.has('KeyA')||keys.has('ArrowLeft'))side--;forward+=-moveVector.y;side+=moveVector.x;const len=Math.hypot(forward,side);if(len>1){forward/=len;side/=len;}moving=len>.08;const speed=(keys.has('ShiftLeft')||keys.has('ShiftRight')?8.2:5.1)*(aiming?.78:1);const dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed*dt,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*speed*dt;let nx=gameCamera.position.x+dx,nz=gameCamera.position.z+dz;if(!isBlocked(nx,gameCamera.position.z,.42))gameCamera.position.x=nx;if(!isBlocked(gameCamera.position.x,nz,.42))gameCamera.position.z=nz;gameCamera.position.x=THREE.MathUtils.clamp(gameCamera.position.x,-46,46);gameCamera.position.z=THREE.MathUtils.clamp(gameCamera.position.z,-46,46);
  if(jumpQueued&&gameCamera.position.y<=1.71)velocityY=5.1;jumpQueued=false;velocityY-=14*dt;gameCamera.position.y+=velocityY*dt;if(gameCamera.position.y<1.7){gameCamera.position.y=1.7;velocityY=0;}gameCamera.rotation.y=yaw;camera.rotation.x=pitch;camera.fov=THREE.MathUtils.damp(camera.fov,aiming?57:76,8,dt);camera.updateProjectionMatrix();
}
function visibleToPlayer(bot,dist){if(dist>31)return false;const steps=Math.ceil(dist/1.6),dx=(gameCamera.position.x-bot.x)/steps,dz=(gameCamera.position.z-bot.z)/steps;for(let i=1;i<steps;i++){const x=bot.x+dx*i,z=bot.z+dz*i;if(isBlocked(x,z,.1))return false;}return true;}
