  const px=gameCamera.position.x,pz=gameCamera.position.z,dx=px-b.x,dz=pz-b.z,dist=Math.hypot(dx,dz)||.001;b.group.rotation.y=Math.atan2(-dx,-dz);const desired=dist>11?1:dist<6?-.45:0;if(desired){let nx=b.x+dx/dist*b.speed*desired*dt,nz=b.z+dz/dist*b.speed*desired*dt;if(isBlocked(nx,nz,.45)){b.targetX=(Math.random()-.5)*60;b.targetZ=(Math.random()-.5)*60;}else{b.x=nx;b.z=nz;b.group.position.set(b.x,Math.abs(Math.sin(time*7+b.phase))*.045, b.z);}}
