const moveZone=$('#move-zone'),lookZone=$('#look-zone'),stick=$('#stick-knob');
moveZone.addEventListener('pointerdown',e=>{if(!playing)return;movePointer=e.pointerId;moveZone.setPointerCapture(e.pointerId);updateStick(e);e.preventDefault();});
function updateStick(e){const r=moveZone.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=Math.min(r.width,r.height)*.33,len=Math.hypot(dx,dy),scale=len>max?max/len:1;moveVector.set(dx*scale/max,-dy*scale/max);stick.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
moveZone.addEventListener('pointermove',e=>{if(e.pointerId===movePointer)updateStick(e);});
function releaseMove(e){if(e.pointerId!==movePointer)return;movePointer=null;moveVector.set(0,0);stick.style.transform='translate(0,0)';}
moveZone.addEventListener('pointerup',releaseMove);moveZone.addEventListener('pointercancel',releaseMove);
lookZone.addEventListener('pointerdown',e=>{if(!playing)return;lookPointer=e.pointerId;lastTouchX=e.clientX;lastTouchY=e.clientY;lookZone.setPointerCapture(e.pointerId);e.preventDefault();});
lookZone.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer)return;const dx=e.clientX-lastTouchX,dy=e.clientY-lastTouchY;lastTouchX=e.clientX;lastTouchY=e.clientY;yaw-=dx*.0052;pitch=THREE.MathUtils.clamp(pitch-dy*.0048,-1.35,1.35);});
function releaseLook(e){if(e.pointerId===lookPointer)lookPointer=null;}
lookZone.addEventListener('pointerup',releaseLook);lookZone.addEventListener('pointercancel',releaseLook);
const fireButton=$('#fire-touch'),aimButton=$('#aim-touch');
fireButton.addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;fireButton.setPointerCapture(e.pointerId);fire();});
['pointerup','pointercancel','lostpointercapture'].forEach(type=>fireButton.addEventListener(type,()=>fireHeld=false));
aimButton.addEventListener('pointerdown',e=>{e.preventDefault();aiming=true;aimButton.classList.add('pressed');aimButton.setPointerCapture(e.pointerId);});
['pointerup','pointercancel','lostpointercapture'].forEach(type=>aimButton.addEventListener(type,()=>{aiming=false;aimButton.classList.remove('pressed');}));
$('#reload-touch').addEventListener('pointerdown',e=>{e.preventDefault();reload();});$('#jump-touch').addEventListener('pointerdown',e=>{e.preventDefault();jumpQueued=true;});
world.addEventListener('click',()=>{if(!playing||paused)return;if(!isMobile()&&document.pointerLockElement!==world){world.requestPointerLock?.();return;}fireHeld=true;fire();});
window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')fireHeld=false;});
window.addEventListener('contextmenu',e=>e.preventDefault());
